        mockConstructor = mock(Constructor.class);
        mockContext = mock(ExpressionContext.class);
        constructorFunction = new ConstructorFunction(mockConstructor);
    }

    @Test
    @DisplayName("Test invoke with null parameters")
    void testInvokeWithNullParameters() throws Exception {
        when(mockConstructor.getParameterTypes()).thenReturn(new Class[0]);
        when(mockConstructor.newInstance(any())).thenReturn("testObject");

        Object result = constructorFunction.invoke(mockContext, null);

        assertEquals("testObject", result);
        verify(mockConstructor).newInstance(new Object[0]);
    }

    @Test
    @DisplayName("Test invoke with empty parameters array")
    void testInvokeWithEmptyParameters() throws Exception {
        when(mockConstructor.getParameterTypes()).thenReturn(new Class[0]);
        when(mockConstructor.newInstance(any())).thenReturn("testObject");

        Object result = constructorFunction.invoke(mockContext, new Object[0]);

        assertEquals("testObject", result);
        verify(mockConstructor).newInstance(new Object[0]);
    }

    @Test
    @DisplayName("Test invoke with ExpressionContext as first parameter")
    void testInvokeWithExpressionContextParameter() throws Exception {
        Class<?>[] paramTypes = {ExpressionContext.class, String.class};
        when(mockConstructor.getParameterTypes()).thenReturn(paramTypes);
        when(mockConstructor.newInstance(any())).thenReturn("testObject");

        Object[] parameters = {"param1"};
        Object result = constructorFunction.invoke(mockContext, parameters);

        assertEquals("testObject", result);
        Object[] expectedArgs = {mockContext, "param1"};
        verify(mockConstructor).newInstance(expectedArgs);
    }

    @Test
    @DisplayName("Test invoke without ExpressionContext parameter")
    void testInvokeWithoutExpressionContextParameter() throws Exception {
        Class<?>[] paramTypes = {String.class, Integer.class};
        when(mockConstructor.getParameterTypes()).thenReturn(paramTypes);
        when(mockConstructor.newInstance(any())).thenReturn("testObject");

        Object[] parameters = {"param1", 42};
        Object result = constructorFunction.invoke(mockContext, parameters);

        assertEquals("testObject", result);
        Object[] expectedArgs = {"param1", 42};
        verify(mockConstructor).newInstance(expectedArgs);
    }

    @Test
    @DisplayName("Test invoke with type conversion")
    void testInvokeWithTypeConversion() throws Exception {
        Class<?>[] paramTypes = {Integer.class};
        when(mockConstructor.getParameterTypes()).thenReturn(paramTypes);
        when(mockConstructor.newInstance(any())).thenReturn("testObject");

        Object[] parameters = {"123"}; // String that can be converted to Integer
        Object result = constructorFunction.invoke(mockContext, parameters);

        assertEquals("testObject", result);
        verify(mockConstructor).newInstance(any());
    }

    @Test
