        Files.write(serviceFile, "service.factory.class".getBytes("UTF-8"));

        // Create a custom classloader that can find our service file
        ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();
        ClassLoader testClassLoader = new ClassLoader() {
            @Override
            public InputStream getResourceAsStream(String name) {
                if (name.equals(serviceId)) {
                    try {
                        return Files.newInputStream(serviceFile);
                    } catch (IOException e) {
                        return null;
                    }
                }
                return super.getResourceAsStream(name);
